<style>
:root{--ink:#182c49;--muted:#607089;--line:#e1e8f1;--blue:#315ce7}
*{box-sizing:border-box}body{font:14px/1.6 "Segoe UI",sans-serif;background:#f3f6fb;color:var(--ink);margin:0}main{max-width:1440px;margin:auto;padding:32px 40px 64px}.appbar{height:70px;background:#142744;color:white;display:flex;justify-content:space-between;align-items:center;padding:0 40px}.brand{font-size:19px;font-weight:800;letter-spacing:2px}.appbar small{color:#bacbe2}.appbar a{color:white}h1{font-size:30px;letter-spacing:-1px;line-height:1.2;margin:18px 0 12px}h2{font-size:19px;margin:0 0 16px}a{color:#315ce7;text-decoration:none;font-weight:600}a:hover{text-decoration:underline}p{margin:10px 0}.muted{color:var(--muted)}.box,.panel{background:white;border:1px solid var(--line);border-radius:18px;padding:24px;margin:22px 0;box-shadow:0 5px 22px #18315305}.box{overflow:auto}input,select,textarea{font:inherit;padding:10px 12px;border:1px solid #cbd6e5;border-radius:9px;background:#fff;color:var(--ink);max-width:100%}input:focus,select:focus,textarea:focus{outline:3px solid #dce6ff;border-color:var(--blue)}button,.button{font:600 13px "Segoe UI",sans-serif;background:var(--blue);color:white;border:0;border-radius:9px;padding:12px 17px;cursor:pointer;display:inline-block;text-decoration:none;box-shadow:0 3px 8px #315ce721}button:hover,.button:hover{background:#2449be;text-decoration:none}label{font-size:13px;font-weight:600;display:inline-block;margin:8px}table{border-collapse:collapse;width:100%}th{background:#f5f8fc;color:#5e7089;font-size:11px;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap}td,th{padding:16px 13px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}tbody tr:hover{background:#f9fbff}tbody tr:last-child td{border-bottom:0}td a{font-size:12px}td form{margin-bottom:8px}td textarea{min-width:150px;width:180px;min-height:62px}input[type=number]{width:100px}.error,.notice{padding:14px 18px;border-radius:12px;margin:16px 0}.error{background:#fff0f0;color:#a42838;border:1px solid #ffd3d3}.notice{background:#eaf8f0;color:#216445;border:1px solid #cbead8}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:25px 0}.stat{padding:20px 23px;border:1px solid var(--line);border-radius:16px;background:white;border-top:3px solid #6387ed}.stat span{color:var(--muted);display:block;font-size:12px}.stat strong{font-size:26px;display:block;margin-top:6px;line-height:1.3}.badge{display:inline-block;padding:5px 10px;background:#edf2ff;color:#3757a6;border-radius:20px;font-size:12px;font-weight:700}.badge.good{background:#e7f6ed;color:#24774c}.badge.warn{background:#fff2df;color:#956013}.badge.bad{background:#ffebed;color:#ae3e4b}.columns{display:grid;grid-template-columns:minmax(300px,390px) minmax(0,1fr);gap:26px;align-items:start}.columns .panel{margin-top:0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.repair-form label{display:block;margin:12px 0 5px}.repair-form input,.repair-form select,.repair-form textarea{width:100%}.repair-form textarea{min-height:100px}.timeline{border-left:2px solid #dae3f1;padding-left:22px;margin-left:8px}.timeline article{position:relative;background:white;border:1px solid var(--line);border-radius:14px;padding:20px;margin:0 0 18px}.timeline article:before{content:"";position:absolute;left:-29px;top:24px;width:10px;height:10px;background:#537be2;border:3px solid #f3f6fb;border-radius:50%}.text{white-space:pre-wrap;overflow-wrap:anywhere}.empty{padding:28px;text-align:center;border:1px dashed #c5d2e5;border-radius:12px;color:var(--muted)}.section-head{display:flex;justify-content:space-between;align-items:center;margin:4px 0 18px}.section-head h2{margin:0}.actions{display:flex;gap:10px;flex-wrap:wrap}
@media(max-width:900px){.columns{grid-template-columns:1fr}main{padding:24px 18px}.appbar{padding:0 18px}.stats{gap:9px}.stat{padding:16px}.stat strong{font-size:21px}}@media(max-width:520px){h1{font-size:25px}.stats{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.box,.panel{padding:17px}.appbar small{display:none}label{display:block;margin:10px 0}.box input[type=month],.box input[type=date]{width:100%}}
</style>
